pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount, uint256 prePlayPot) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforePot;
        try c.pot() returns (uint256 __r) { beforePot = __r; } catch { return; }
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterPot;
        try c.pot() returns (uint256 __r) { afterPot = __r; } catch { return; }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        assertTrue((reverted ? amount != 10 : amount == 10) &&
            (reverted ? afterPot == beforePot : (afterPot == 0 || afterPot == beforePot + 10)));
    }

    function testFuzz_run(uint256 amount, uint256 prePlayPot) public {
        _run(amount, prePlayPot);
    }

    receive() external payable {}
}
